package com.example.rokidkeyboardbridge;
public class CapturePressurePolicyTest {
 static int n;static final long MB=1024L*1024;static void ok(boolean b,String label){if(!b)throw new AssertionError(label);n++;}
 static String meeting(int mode,boolean stopping,int queued,boolean low,long heap,long now,long last){return MeetingCameraPolicy.reason(mode,stopping,queued,low,heap*MB,now,last);}
 public static void main(String[]args){
  ok(meeting(0,false,0,false,64,100000,0).equals("AUDIO_ONLY"),"record-only never starts camera");ok(meeting(3,false,0,false,64,100000,0).equals("AUDIO_ONLY"),"sound mode never starts camera");for(int mode:new int[]{1,2})ok(meeting(mode,false,0,false,64,100000,0).isEmpty(),"vision modes may capture");ok(meeting(2,true,0,false,64,100000,0).equals("STOPPING"),"stop processing wins");ok(meeting(2,false,17,false,64,100000,0).equals("AUDIO_BACKLOG"),"disk backlog wins");ok(meeting(2,false,0,true,64,100000,0).equals("LOW_MEMORY"),"system pressure blocks camera");ok(meeting(2,false,0,false,31,100000,0).equals("HEAP_RESERVE"),"heap reserve blocks camera");ok(meeting(2,false,0,false,64,129999,100000).equals("INTERVAL30"),"normal interval protected");ok(meeting(2,false,0,false,64,130000,100000).isEmpty(),"normal boundary allowed");ok(meeting(2,false,9,false,64,130000,100000).equals("INTERVAL60"),"moderate backlog slows optional camera");ok(meeting(2,false,9,false,64,160000,100000).isEmpty(),"slow boundary allowed");ok(meeting(2,false,0,false,47,130000,100000).equals("INTERVAL60"),"moderate heap slows optional camera");ok(meeting(2,false,0,false,48,130000,100000).isEmpty(),"heap threshold stable");ok(meeting(2,false,0,false,64,99999,100000).equals("CLOCK"),"rollback fails closed");
  long now=100000;ok(KeepTopicImagePolicy.reason(now,95000,0,MB,64*MB,false,true).equals("KEEP_WAIT"),"KEEP ownership reported");ok(KeepTopicImagePolicy.reason(now,0,0,MB,64*MB,false,false).equals("NO_FRAME"),"unprepared reported");ok(KeepTopicImagePolicy.reason(now,84999,0,MB,64*MB,false,false).equals("STALE"),"old saved frame reported");ok(KeepTopicImagePolicy.reason(now,95000,90000,MB,64*MB,false,false).equals("RATE"),"reuse rate reported");ok(KeepTopicImagePolicy.reason(now,95000,0,4*MB,64*MB,false,false).equals("SOURCE_SIZE"),"large encrypted frame rejected before reading");ok(KeepTopicImagePolicy.reason(now,95000,0,MB,35*MB,false,false).equals("HEAP_RESERVE"),"decode headroom protected");ok(KeepTopicImagePolicy.canReuse(now,95000,0,MB,64*MB,false,false),"normal saved frame still usable");ok(!MeetingCameraPolicy.label("AUDIO_BACKLOG").contains("17"),"diagnostics are stable reasons without content");
  System.out.println("PASS concurrent capture pressure "+n+" checks");
 }
}
